<?php
require 'config.php';require_login();$pageTitle='Reports';$active='reports';$rows=$conn->query("SELECT s.*,(SELECT COUNT(*) FROM attendance a WHERE a.student_id=s.id AND a.status='Present') p,(SELECT COUNT(*) FROM attendance a WHERE a.student_id=s.id) n,(SELECT AVG((m.internal_marks+m.semester_marks)/2) FROM marks m WHERE m.student_id=s.id) av FROM students s ORDER BY department,name");require 'includes/header.php';?>
<div class="heading no-print"><div><p class="eyebrow">INSIGHTS & EXPORTS</p><h1>Student reports</h1><p class="muted">A consolidated view of enrolment, attendance and academic performance.</p></div><button class="btn primary" onclick="window.print()">⤓ Print / Save PDF</button></div><section class="card"><div class="cardhead"><div><h2>Student summary report</h2><p class="muted">Generated on <?=date('d M Y, h:i A')?></p></div><span class="count"><?=$rows->num_rows?> student records</span></div><div class="tablewrap"><table><thead><tr><th>REGISTER NO.</th><th>STUDENT NAME</th><th>DEPARTMENT / YEAR</th><th>ATTENDANCE</th><th>AVERAGE MARKS</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):$pct=(int)$r['n']?100*(int)$r['p']/(int)$r['n']:null;?><tr><td><?=e($r['register_number'])?></td><td><b><?=e($r['name'])?></b></td><td><?=e($r['department'])?><small>Year <?=$r['year']?></small></td><td><?=$pct===null?'Not recorded':number_format($pct,1).'%'.'<div class="progress"><span style="width:'.min(100,$pct).'%"></span></div>'?></td><td><?=$r['av']===null?'Not recorded':number_format((float)$r['av'],1).'%'?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="empty">No records available to report.</td></tr><?php endif;?></tbody></table></div></section><p class="muted no-print">Tip: In the print window, choose “Save as PDF” to create a PDF copy.</p><?php require 'includes/footer.php';?>